def evolved_p98(x, N, rank, world_size, num_devices,
                 cores_per_device, xm, torch, num_nodes=1):
    # x[i] = (i*3 + 1) % (i%7 + 2) -- position based, no collective
    i = torch.arange(N, device=x.device, dtype=torch.int64)
